rows=[]
for stage,notes in [('final',final),('validation',validation)]:
    raw=json.loads((R/f'docs/natural-assistant/evidence/{stage}/generations.json').read_text())
    for sample,cases in notes.items():
        for i,case in enumerate(cases):
            suffix=['scene','fact-1','fact-2'][i]
            for offset,variant in [(0,'base'),(2,'adapter')]:
                identifier=f'vision:docci/{sample}/{suffix}'
                g=next(g for g in raw if g['id']==identifier and g['variant']==variant)
                rows.append({'stage':stage,'id':identifier,'variant':variant,'judgment':{'p':'pass','f':'fail','u':'uncertain'}[case[offset]],'reason':case[offset+1],'prediction':g['prediction'],'stop_reason':g['stop_reason'],'raw_prediction_sha256':hashlib.sha256(g['prediction'].encode()).hexdigest()})
result={'reviewer_task':'/root/natural_factual_final_20_5','recorded_at':datetime.now(timezone.utc).isoformat(),'read_existing_semantic_reports_before_this_snapshot':False,'scope':'獨立從原圖與完整raw生成判斷；uncertain保留語意邊界，不變更GT／固定selection／已公開計分。不是另一次推論。','cases':rows}
(O/(P+'independent-semantics.json')).write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
print('Preserved independent judgments:',len(rows))
